// Turn each PageSpeed response (or error) into one audit row + normalized findings.
const prospects = $('Select Prospects').all();
const strategy = $('Audit Parameters').first().json.strategy;
const pct = v => (typeof v === 'number' ? Math.round(v * 100) : null);
const failed = (aud, id) => aud[id] && aud[id].score !== null && aud[id].score !== undefined && aud[id].score < 1;
const out = [];
$input.all().forEach((it, i) => {
  const pr = prospects[i].json;
  const base = { prospect_id: pr.prospect_id, url: pr.url, strategy };
  const body = it.json;
  const lh = body && body.lighthouseResult;
  if (!lh) {
    const msg = (body && (body.error && (body.error.message || body.error))) || 'no lighthouseResult in response';
    out.push({ json: { ...base, status: 'error', scores: null, metrics: null, error: String(typeof msg === 'string' ? msg : JSON.stringify(msg)).slice(0, 500), findings: [] } });
    return;
  }
  const cat = lh.categories || {}, aud = lh.audits || {};
  const scores = { performance: pct(cat.performance?.score), seo: pct(cat.seo?.score), accessibility: pct(cat.accessibility?.score), best_practices: pct(cat['best-practices']?.score) };
  const metrics = { lcp_ms: Math.round(aud['largest-contentful-paint']?.numericValue ?? 0) || null, cls: aud['cumulative-layout-shift']?.numericValue ?? null, tbt_ms: Math.round(aud['total-blocking-time']?.numericValue ?? 0), fcp_ms: Math.round(aud['first-contentful-paint']?.numericValue ?? 0) || null };
  const f = [];
  const add = (check_name, severity, evidence, business_impact_text) => f.push({ check_name, severity, evidence, business_impact_text });
  if (scores.performance !== null && scores.performance < 50) add('performance', 'high', `Mobile performance score ${scores.performance}/100; largest content takes ${(metrics.lcp_ms/1000).toFixed(1)}s`, 'On a phone, your site is slow to load, and many visitors leave before it finishes.');
  else if (scores.performance !== null && scores.performance < 90) add('performance', 'medium', `Mobile performance score ${scores.performance}/100`, 'Your site is a little slow on phones, which costs you some visitors and hurts search ranking.');
  if (failed(aud, 'viewport')) add('mobile-viewport', 'high', 'No mobile viewport meta tag', 'Your site is not set up for phone screens, so customers have to pinch and zoom to read it.');
  if (failed(aud, 'is-on-https')) add('https', 'high', 'Page is not served over HTTPS', 'Browsers warn visitors that your site is "Not secure", which scares customers away.');
  if (failed(aud, 'tap-targets')) add('tap-targets', 'medium', 'Buttons/links too small or too close together', 'On a phone, buttons and phone links are hard to tap, so customers give up before calling or booking.');
  if (failed(aud, 'font-size')) add('font-size', 'medium', 'Text too small to read on mobile', 'Text is too small to read comfortably on a phone.');
  if (failed(aud, 'document-title')) add('title', 'medium', 'Page has no <title>', 'Google has no title to show for your business in search results.');
  if (failed(aud, 'meta-description')) add('meta-description', 'medium', 'No meta description', 'Search results show a random snippet instead of a message that gets people to call you.');
  if (scores.accessibility !== null && scores.accessibility < 70) add('accessibility', 'low', `Accessibility score ${scores.accessibility}/100`, 'Some customers, including older ones, may struggle to use your site.');
  if (scores.seo !== null && scores.seo < 80) add('seo', 'medium', `SEO score ${scores.seo}/100`, 'Basic search-engine setup is missing, making it harder for local customers to find you on Google.');
  out.push({ json: { ...base, status: 'ok', scores, metrics, error: null, findings: f } });
});
return out;
